public class Initials2
{
	public static void main(String[] args)
	{
		//Khutwa 1: Ta3rif al-ism
		String fullName = "Jun Filib Smit";
		//Khutwa 2: Istikhraj al-ism al-awwal
		String first = fullName.substring(0, 4);
		//Khutwa 3: Istikhraj al-harf al-wasat
		String middleInitial = fullName.substring(5, 6);
		//Khutwa 4: Istikhraj al-ism al-akhir
		String last = fullName.substring(13, fullName.length());
		//Khutwa 5: Bina al-ism min al-ism al-awwal, al-harf al-wasat, wa al-ism al-akhir
		String name = first + " " + middleInitial + ". " + last;
		System.out.println(name);
	}
}
